def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    result = v1 * v2 * 0.01

    return {
        "value": result,
        "trace": {
            "contracted_backlog": v1,
            "fixed_price_percentage": v2,
            "fixed_price_backlog": result,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
